"""Fifth generator: rich ASTs (aggregates/quantifiers/scale/add) + dense small data."""
import json, random

NUM = ("TIME", "SIZE", "COUNT")


def gen(rng):
    K = rng.choice([1, 1, 2, 2, 3, 3, 4])
    fields = []
    for nm in rng.sample(["a", "b", "c", "d", "e"], rng.randint(1, 4)):
        t = rng.choice(["FLAG", "SIZE", "COUNT", "ID"])
        if t == "FLAG":
            fields.append({"name": nm, "type": "FLAG"})
        elif t == "ID":
            fields.append({"name": nm, "type": "ID", "values": rng.sample(["x","y","z"], rng.randint(1,2))})
        else:
            fields.append({"name": nm, "type": t, "min": 0, "max": rng.choice([0,1,2])})

    def val(f):
        if f["type"] == "FLAG":
            return rng.random() < 0.7
        if f["type"] == "ID":
            return rng.choice(f["values"])
        return rng.randint(f["min"], f["max"])

    def term(ftype, quant, depth):
        cands = [f for f in fields if f["type"] == ftype]
        if not cands:
            if ftype == "FLAG": return {"const": rng.choice([True, False]), "type": "FLAG"}
            if ftype == "ID": return {"const": "x", "type": "ID"}
            return {"const": rng.randint(0, 2), "type": ftype}
        r = rng.random()
        if r < 0.5:
            if quant and rng.random() < 0.6:
                return {"field": rng.choice(cands)["name"], "at": "$"}
            return {"field": rng.choice(cands)["name"], "at": rng.randrange(K)}
        if ftype in NUM and depth < 4 and r < 0.85:
            kind = rng.choice(["scale", "add", "sum", "mean", "min", "max"])
            if kind == "scale":
                return {"scale": rng.randint(-2, 3), "term": term(ftype, quant, depth+1)}
            if kind == "add":
                return {"add": [term(ftype, quant, depth+1), term(ftype, quant, depth+1)]}
            f = rng.choice(cands)
            a = rng.randrange(K); z = rng.randint(a, K-1)
            return {"aggregate": kind, "field": f["name"], "from": a, "to": z}
        if ftype == "FLAG":
            return {"const": rng.choice([True, False]), "type": "FLAG"}
        if ftype == "ID":
            return {"const": rng.choice(f["values"]), "type": "ID"}
        return {"const": rng.randint(0, 2), "type": ftype}

    atoms = []
    for _ in range(rng.randint(1, 5)):
        ftype = rng.choice([f["type"] for f in fields])
        quant = rng.random() < 0.35
        ops = ["eq","ne","lt","le","gt","ge"] if ftype in NUM else ["eq","ne"]
        body = {"cmp": rng.choice(ops), "left": term(ftype, quant, 1), "right": term(ftype, quant, quant)}
        if quant:
            a = rng.randrange(K); z = rng.randint(a, K-1)
            atoms.append({"quantifier": rng.choice(["any","all"]), "from": a, "to": z, "predicate": body})
        else:
            atoms.append(body)
    while atoms and rng.random() < 0.45 and len(atoms) < 8:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))

    def mk(tid, srcs, n):
        ts = rng.sample(range(-20, 300), n) if n else []
        return {"id": tid, "source": rng.choice(srcs),
                "rows": [{"t": t, "values": [val(f) for f in fields]} for t in ts]}

    srcs = ["s%d" % i for i in range(rng.choice([1,1,2,3]))]
    train = [mk("tr%d"%i, srcs, rng.randint(max(1,K-1), K+rng.randint(0,4))) for i in range(rng.randint(1,3))]
    probes = [mk("pr%d"%i, srcs, rng.randint(1, 3)) for i in range(rng.randint(1, 2))]
    queries = [mk("q%d"%i, srcs, rng.randint(0, 5)) for i in range(rng.randint(0, 3))]
    return {"version":1,"window":K,"schema":fields,"atoms":atoms,
            "policy":{"max_width":rng.choice([1,2,2,3,3,4]),
                      "min_support":rng.choice([1,1,1,1,2]),
                      "min_witness":rng.choice([1,1,1,1,2])},
            "train":train,"probes":probes,"queries":queries}
PYEOF
